/* 旧カテゴリーkeyで保存済みのコラムを、新しいカテゴリーへ読み替える */
const GM_CAT_ALIAS = { five:'kokozo', men:'hitori', dup:'gatsuri', noge:'katari', tori:'katari', chuka:'nakama', minato:'lunch', ensei:'toku', kannai:'yokohama', clock:'lunch' };

function gmCategoryStats(){
  return GM_CATEGORIES.map(c => {
    const items = GM_ROWS.filter(c.match);
    const shops = gmDistinctShops(items);
    return Object.assign({}, c, { items, rows:items.length, shops, label:c.name + ' ' + shops + '軒' });
  });
}

/* コラムに付くカテゴリ表示情報 */
function gmCategoryOf(col){
  if(col.catKey){
    const k = GM_CAT_ALIAS[col.catKey] || col.catKey;
    const c = gmCategoryStats().find(x => x.key === k);
    if(c) return { key:c.key, name:c.name, label:c.label, tone:c.tone };
  }
  const name = col.category || 'その他';
  const label = col.catCount ? name + ' ' + col.catCount + (/[軒件本]$/.test(String(col.catCount)) ? '' : '軒') : name;
  return { key:'', name, label, tone:col.catTone || 'indigo' };
}


/* ---------------- ランキングのサムネイル ----------------
   店ごとに写真を1枚。登録した写真はブラウザに保存（管理画面の「ランキングのサムネイル」から追加）。
   未登録の店は、ジャンルの一文字を入れた枠で表示する。 */
const GM_RANK_KEY = 'gm_rank_thumbs_v1';
const GM_RANK_IMG_SEED = { 1:'media/seoul-grill-s.jpg', 2:'media/haruma-pot-s.jpg', 3:'media/koraku-ramen-s.jpg', 15:'media/daikou-ramen-s.jpg' };   // 最初から入っている写真（行番号 → 画像）
const GM_GENRE_MARK = { '中華・餃子':'餃', 'そば・うどん':'麺', 'フレンチ・イタリアン':'洋', '焼鳥・鶏':'鶏', '海鮮・市場':'魚', '居酒屋・食堂':'酒', '肉料理':'肉', 'とんかつ・揚げ物':'揚', 'ラーメン':'拉', 'パン':'麦', 'カフェ':'珈', '鮨・うなぎ':'鮨', '韓国':'韓', 'カレー':'辛', 'その他':'食' };
function gmRankMap(){
  let m; try { m = JSON.parse(localStorage.getItem(GM_RANK_KEY)) || {}; } catch(e){ m = {}; }
  try {
    if(!localStorage.getItem('gm_rank_perm_v1')){          // 光楽を3位へ移した並べ替えに合わせて、保存済みサムネイルの番号を読み替える
      const P = { 9:3, 3:4, 4:5, 5:6, 6:7, 7:8, 8:9 }, o = {};
      for(const k in m){ const n = Number(k); o[P[n] || n] = m[k]; }
      m = o; localStorage.setItem(GM_RANK_KEY, JSON.stringify(m)); localStorage.setItem('gm_rank_perm_v1', '1');
    }
  } catch(e){}
  try {
    if(!localStorage.getItem('gm_rank_perm_v2')){          // 大公を15位へ移した並べ替え（15〜128位は1つ下へ、129位が15位へ）
      const o = {};
      for(const k in m){ const n = Number(k); o[n === 129 ? 15 : (n >= 15 && n <= 128 ? n + 1 : n)] = m[k]; }
      m = o; localStorage.setItem(GM_RANK_KEY, JSON.stringify(m)); localStorage.setItem('gm_rank_perm_v2', '1');
    }
  } catch(e){}
  return m;
}
function gmRankThumb(n){
  const m = gmRankMap();
  if(Object.prototype.hasOwnProperty.call(m, n)) return m[n];
  const seed = GM_RANK_IMG_SEED[n];
  return seed ? ((typeof GM_MEDIA !== 'undefined' && GM_MEDIA[seed]) || seed) : '';
}
function gmSetRankThumb(n, data){
  const m = gmRankMap(); m[n] = data || '';
  try { localStorage.setItem(GM_RANK_KEY, JSON.stringify(m)); return true; }
  catch(e){ alert('保存できませんでした（ブラウザの保存容量がいっぱいの可能性があります）。'); return false; }
}
function gmRankThumbHTML(r){
  const src = gmRankThumb(r.n);
  if(src) return '<span class="rk-th"><img src="' + gmEsc(src) + '" alt="' + gmEsc(r.name) + '" loading="lazy"></span>';
  return '<span class="rk-th rk-th-empty" aria-hidden="true"><b>' + gmEsc(GM_GENRE_MARK[r.genre] || '食') + '</b></span>';
}

/* ---------------- 本文レンダリング ---------------- */
function gmEsc(s){
  return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function gmInline(s){
  return gmEsc(s)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/〔([^〕]*)〕/g, '<span class="stage">$1</span>');
}
function gmRenderBody(body){
  return (body || []).map(p => {
    p = String(p).trim();
    if(!p) return '';
    let mm;
    if((mm = p.match(/^!\[([^\]]*)\]\(([^)\s]+)\)$/))) return '<figure class="am-fig"><img src="' + gmEsc(mm[2]) + '" alt="' + gmEsc(mm[1]) + '" loading="lazy">' + (mm[1] ? '<figcaption>' + gmEsc(mm[1]) + '</figcaption>' : '') + '</figure>';
    if((mm = p.match(/^@video\(([^|)]+)\|([^|)]*)\|([^)]*)\)$/))) return '<figure class="am-fig"><video controls playsinline preload="metadata" src="' + gmEsc(mm[1]) + '"' + (mm[2] ? ' poster="' + gmEsc(mm[2]) + '"' : '') + '></video>' + (mm[3] ? '<figcaption>' + gmEsc(mm[3]) + '</figcaption>' : '') + '</figure>';
    if(/^##\s/.test(p)) return '<h3>' + gmInline(p.replace(/^##\s+/, '')) + '</h3>';
    const lines = p.split('\n');
    if(lines.every(l => /^-\s/.test(l))) return '<ul>' + lines.map(l => '<li>' + gmInline(l.replace(/^-\s+/, '')) + '</li>').join('') + '</ul>';
    if(lines.every(l => /^\d+\.\s/.test(l))) return '<ol>' + lines.map(l => '<li>' + gmInline(l.replace(/^\d+\.\s+/, '')) + '</li>').join('') + '</ol>';
    return '<p>' + lines.map(gmInline).join('<br>') + '</p>';
  }).join('');
}
function gmCharCount(col){
  return (col.body || []).filter(p => !/^(!\[[^\]]*\]\([^)]*\)|@video\([^)]*\))$/.test(String(p).trim())).join('').replace(/^(##\s|-\s|\d+\.\s)/gm, '').replace(/\s/g, '').length;
}
function gmReadMinutes(col){ return Math.max(1, Math.round(gmCharCount(col) / 500)); }

/* ---------------- 保存 ---------------- */
const GM_KEYS = { CUSTOM:'gm_custom_columns_v1', DELETED:'gm_deleted_ids_v1' };

function gmLoad(key){ try { return JSON.parse(localStorage.getItem(key)) || []; } catch(e){ return []; } }
function gmSave(key, list){
  try { localStorage.setItem(key, JSON.stringify(list)); return true; }
  catch(e){ alert('保存できませんでした（ブラウザの保存容量がいっぱいの可能性があります）。写真を小さくするか、不要なコラムを削除してください。'); return false; }
}

function gmGetAllColumns(){
  const custom = gmLoad(GM_KEYS.CUSTOM);
  const deleted = new Set(gmLoad(GM_KEYS.DELETED));
  const customIds = new Set(custom.map(c => c.id));
  const seed = GM_SEED_COLUMNS.filter(c => !deleted.has(c.id) && !customIds.has(c.id));
  const merged = [...custom, ...seed];
  merged.sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
  return merged;
}
function gmUpsertColumn(col){
  const custom = gmLoad(GM_KEYS.CUSTOM);
  const i = custom.findIndex(c => c.id === col.id);
  if(i >= 0) custom[i] = col; else custom.unshift(col);
  return gmSave(GM_KEYS.CUSTOM, custom);
}
function gmDeleteColumn(id){
  gmSave(GM_KEYS.CUSTOM, gmLoad(GM_KEYS.CUSTOM).filter(c => c.id !== id));
  const d = gmLoad(GM_KEYS.DELETED);
  if(!d.includes(id)){ d.push(id); gmSave(GM_KEYS.DELETED, d); }
}
function gmGenerateId(){ return 'col-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 7); }

/* アップロード画像を長辺1000pxのJPEGに縮小（localStorageの容量対策） */
function gmCompressImage(file, maxW, quality){
  maxW = maxW || 1000; quality = quality || 0.8;
  return new Promise((resolve, reject) => {
    const fr = new FileReader();
    fr.onerror = reject;
    fr.onload = () => {
      const img = new Image();
      img.onerror = reject;
      img.onload = () => {
        const k = Math.min(1, maxW / Math.max(img.width, img.height));
        const c = document.createElement('canvas');
        c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);
        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
        resolve(c.toDataURL('image/jpeg', quality));
      };
      img.src = fr.result;
    };
    fr.readAsDataURL(file);
  });
}

/* ============================================================
   写真スロット（外観 / 内観 / 料理）
   実写真が未登録のときは、下のイラストで代替表示する。
============================================================ */
let GM_UID = 0;
const GM_PHOTO_KINDS = { exterior:'外観', interior:'内観', dish:'料理' };
const GM_DISHES = { noodle:'麺（ラーメン・そば・うどん）', gyoza:'餃子・中華', skewer:'焼鳥・串', sushi:'鮨・和食' };
const GM_MINCHO = "'Shippori Mincho B1','Hiragino Mincho ProN','Yu Mincho',serif";

function gmSvg(inner){
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 300" preserveAspectRatio="xMidYMid slice" role="img" aria-hidden="true">' + inner + '</svg>';
}

/* ---- 写真が未登録の枠：原型どおりの、文字だけの静かなプレースホルダー ---- */
const GM_PH_STYLE = {
  exterior:{ en:'EXTERIOR', c1:'#2a2118', c2:'#131009', mark:null },
  interior:{ en:'INTERIOR', c1:'#231c14', c2:'#0f0c08', mark:'席' },
  dish:    { en:'CUISINE',  c1:'#2d2016', c2:'#120c08', mark:'味' }
};
function gmPlaceholder(kind, col){
  const u = ++GM_UID, st = GM_PH_STYLE[kind] || GM_PH_STYLE.dish;
  const mark = st.mark || ((col && (col.mono || (col.title || '').trim().charAt(0))) || '食');
  return gmSvg(
    '<defs><linearGradient id="pg' + u + '" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="' + st.c1 + '"/><stop offset="1" stop-color="' + st.c2 + '"/></linearGradient>' +
    '<pattern id="pd' + u + '" width="3" height="3" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".5" fill="#fff" fill-opacity=".05"/></pattern></defs>' +
    '<rect width="400" height="300" fill="url(#pg' + u + ')"/><rect width="400" height="300" fill="url(#pd' + u + ')"/>' +
    '<text x="200" y="212" text-anchor="middle" font-family="' + GM_MINCHO + '" font-weight="700" font-size="150" fill="#e8c97a" fill-opacity=".085">' + gmEsc(mark) + '</text>'
  );
}

function gmIllustration(kind, col){
  return gmPlaceholder(kind, col);
}

/* 写真1枚分のHTML。実写真があれば <img>、なければイラスト */
function gmPhoto(col, kind){
  const src = col.photos && col.photos[kind];
  const label = GM_PHOTO_KINDS[kind];
  if(src){
    return '<figure class="ph ph-real"><img src="' + gmEsc(src) + '" alt="' + gmEsc(label) + '" loading="lazy"><figcaption>' + label + '</figcaption></figure>';
  }
  return '<figure class="ph ph-ill">' + gmIllustration(kind, col) + '<figcaption>' + label + '</figcaption></figure>';
}

/* カード・ピックアップ用のメディア。thumb（サムネイル）があればそれを、なければ外観/内観/料理のモザイク */
function gmHasVideo(col){ return (col.gallery || []).some(g => g.type === 'video'); }
function gmCardMedia(col){
  if(col.thumb){
    return '<div class="mosaic thumb1"><figure class="ph ph-real"><img src="' + gmEsc(col.thumb) + '" alt="' + gmEsc(col.title) + '" loading="lazy">' +
      (gmHasVideo(col) ? '<span class="vbadge">▶ 動画あり</span>' : '') + '</figure></div>';
  }
  return '<div class="mosaic">' + gmPhoto(col, 'dish') + gmPhoto(col, 'exterior') + gmPhoto(col, 'interior') + '</div>';
}
/* 記事上部のギャラリー（大きな1枚＋サムネイルの帯。動画も並べられる） */
function gmGalleryHTML(col){
  const g = col.gallery || [];
  if(!g.length) return '';
  return '<div class="gal" data-gal>' +
    '<div class="gal-main" data-galmain></div>' +
    '<p class="gal-cap" data-galcap></p>' +
    '<div class="gal-strip" role="tablist">' + g.map((it, i) =>
      '<button type="button" class="gal-th' + (i === 0 ? ' on' : '') + '" data-i="' + i + '" role="tab" aria-label="' + gmEsc(it.type === 'video' ? '動画' : '写真') + (i + 1) + '">' +
      '<img src="' + gmEsc(it.thumb || it.src) + '" alt="" loading="lazy">' + (it.type === 'video' ? '<span class="play">▶</span>' : '') + '</button>').join('') + '</div></div>';
}
function gmGalleryMount(root, col){
  const g = col.gallery || [], box = root.querySelector('[data-gal]');
  if(!box) return;
  const main = box.querySelector('[data-galmain]'), cap = box.querySelector('[data-galcap]');
  function show(i){
    const it = g[i];
    main.innerHTML = it.type === 'video'
      ? '<video controls playsinline preload="metadata" src="' + gmEsc(it.src) + '"' + (it.poster ? ' poster="' + gmEsc(it.poster) + '"' : '') + '></video>'
      : '<img src="' + gmEsc(it.src) + '" alt="' + gmEsc(it.caption || '') + '">';
    cap.textContent = it.caption || '';
    box.querySelectorAll('.gal-th').forEach((b, k) => b.classList.toggle('on', k === i));
  }
  box.querySelectorAll('.gal-th').forEach(b => b.addEventListener('click', () => show(Number(b.dataset.i))));
  show(0);
}

