/* 写真・動画は media.js（埋め込み版）があればそれを使い、なければ media/ フォルダのパスのまま表示する */
function gmResolveMedia(v){
  if(typeof v === 'string') return (typeof GM_MEDIA !== 'undefined' && GM_MEDIA[v]) || v;
  if(Array.isArray(v)) return v.map(gmResolveMedia);
  if(v && typeof v === 'object'){ for(const k in v) v[k] = gmResolveMedia(v[k]); }
  return v;
}
GM_SEED_COLUMNS.forEach(gmResolveMedia);
